python3 - <<'EOF'
import json, logging, os, sys
class JsonFormatter(logging.Formatter):
    def format(self, record):
        return json.dumps({"trace_id": os.environ.get("TRACE_ID", "-"), "ts": self.formatTime(record), "level": record.levelname, "msg": record.getMessage(), "service": "api"})
h = logging.StreamHandler(sys.stdout); h.setFormatter(JsonFormatter())
log = logging.getLogger(); log.addHandler(h); log.setLevel("INFO")
log.info("request handled")
EOF
